function t(s,lang='en'){if(!s||lang==='en')return s;const exact=P[s]?.[lang];if(exact)return exact;let m;if((m=String(s).match(/^Channel\s+(\d+)$/)))return (P['Channel']?.[lang]||'Channel')+' '+m[1];if((m=String(s).match(/^(\d+) notes in current take$/)))return m[1]+' '+(P['notes in current take']?.[lang]||'notes in current take');if(lang==='lv'&&(m=String(s).match(/^Current part:\s*(.+)$/)))return 'Pašreizējā partija: '+m[1];if(lang==='lv'&&(m=String(s).match(/^System\s+(\d+)$/)))return 'Sistēma '+m[1];if(lang==='lv'&&(m=String(s).match(/^Current score key\s+—\s+(.+)$/)))return 'Pašreizējā tonalitāte — '+m[1];if(lang==='lv'&&(m=String(s).match(/^Clear bar\s+(\d+)$/)))return 'Notīrīt '+m[1]+'. takti';if(lang==='lv'&&(m=String(s).match(/^Bar\s+(\d+)$/)))return 'Takts '+m[1];if(lang==='lv'&&(m=String(s).match(/^Bar\s+(\d+),\s*beat\s+(.+)$/)))return 'Takts '+m[1]+', sitiens '+m[2];if(lang==='lv'&&(m=String(s).match(/^Selected:\s*(.+)$/)))return 'Izvēlēts: '+m[1];if(lang==='lv'&&(m=String(s).match(/^(\d+) symbols$/)))return m[1]+' simboli';if(lang==='lv'&&(m=String(s).match(/^Cursor:\s*bar\s+(\d+),\s*beat\s+(.+)$/)))return 'Kursors: takts '+m[1]+', sitiens '+m[2];if(lang==='lv'&&(m=String(s).match(/^(\d+) notes$/)))return m[1]+' notis';if(lang==='lv'&&(m=String(s).match(/^for\s+(.+)$/)))return 'instrumentam '+m[1];if(lang==='lv'&&(m=String(s).match(/^(\d+) melody notes(?: · (\d+) chords)? · (\d+) sec$/)))return m[1]+' melodijas notis'+(m[2]?' · '+m[2]+' akordi':'')+' · '+m[3]+' sek.';if(lang==='lv'&&(m=String(s).match(/^Target:\s*(.+) · Range (.+)–(.+) · (.+) · (.+) grid$/)))return 'Mērķis: '+m[1]+' · Diapazons '+m[2]+'–'+m[3]+' · '+t(m[4],lang)+' · '+m[5]+' režģis';if(lang==='lv'&&(m=String(s).match(/^Preparing (.+)…$/)))return 'Sagatavo '+m[1]+'…';if(lang==='lv'&&(m=String(s).match(/^(\d+) editable melody notes detected(?: plus (\d+) chord suggestions)?\.$/)))return m[1]+' rediģējamas melodijas notis atrastas'+(m[2]?' un '+m[2]+' akordu ieteikumi':'')+'.';return s}
function translate(root,lang='en'){if(!root)return;const attrs=['placeholder','title','aria-label'];const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){const el=n.parentElement;if(!el||['SCRIPT','STYLE'].includes(el.tagName)||el.closest?.('[data-no-i18n]'))continue;const raw=n.nodeValue,trim=raw.trim();if(!trim)continue;const tr=t(trim,lang);if(tr!==trim)n.nodeValue=raw.replace(trim,tr)}root.querySelectorAll?.('*').forEach(e=>{if(e.closest?.('[data-no-i18n]'))return;for(const a of attrs){const raw=e.getAttribute?.(a);if(!raw)continue;const tr=t(raw,lang);if(tr!==raw)e.setAttribute(a,tr)}});}

